export type Result<T, E> = { ok: true; value: T } | { ok: false; error: E };

export const ok = <T>(value: T): Result<T, never> => ({ ok: true, value });
export const err = <E>(error: E): Result<never, E> => ({ ok: false, error });

export function mapResult<T, U, E>(r: Result<T, E>, fn: (v: T) => U): Result<U, E> {
  return r.ok ? ok(fn(r.value)) : r;
}

export function assertNever(x: never): never {
  throw new Error(`Unexpected value: ${JSON.stringify(x)}`);
}

export type ExtractParams<Path extends string> =
  Path extends `${string}:${infer Param}/${infer Rest}`
    ? Param | ExtractParams<Rest>
    : Path extends `${string}:${infer Param}`
      ? Param
      : never;

export type ParamsRecord<Path extends string> = [ExtractParams<Path>] extends [never]
  ? Record<string, never>
  : Record<ExtractParams<Path>, string>;

export function buildUrl<Path extends string>(template: Path, params: ParamsRecord<Path>): string {
  return template.replace(/:([a-zA-Z0-9_]+)/g, (_, key: string) =>
    encodeURIComponent((params as Record<string, string>)[key] ?? '')
  );
}

